"use strict";exports.id=135,exports.ids=[135],exports.modules={440:(e,a,i)=>{i.d(a,{Z:()=>t});var n=i(9510);function t({children:e,variant:a="cyan"}){return n.jsx("span",{className:`inline-block px-3 py-1 rounded-lg text-xs font-medium border ${{cyan:"bg-brand-cyan/10 text-brand-cyan border-brand-cyan/20",green:"bg-green-500/10 text-green-400 border-green-500/20",yellow:"bg-yellow-500/10 text-yellow-400 border-yellow-500/20",red:"bg-red-500/10 text-red-400 border-red-500/20",gray:"bg-gray-500/10 text-gray-400 border-gray-500/20"}[a]}`,children:e})}},668:(e,a,i)=>{i.d(a,{v:()=>n});let n=[{id:"hr-case-ar-001",language:"ar",slug:"chest-pneumonia",title:"ذات الرئة — حالة سريرية",modality:"أشعة سينية",region:"الصدر",clinicalContext:"مريض يبلغ من العمر 45 عامًا يعاني من السعال والحمى منذ 5 أيام.",indication:"تقييم أعراض عدوى تنفسية سفلية مع الاشتباه في وجود التهاب رئوي.",technique:"أشعة سينية للصدر مع تقييم الوضعية، جودة الاستنشاق، التعرض، والأنسجة الرئوية والجنبيّة.",image:"/assets/images/ar/cases/xray/chest-pneumonia.jpg",imageDescription:"صورة أشعة سينية للصدر تُظهر عتامة رئوية موضعية.",keyFindings:"توجد عتامة هوائية موضعية في المنطقة السفلية من الرئة اليمنى، مع وجود Air Bronchograms ضمن منطقة التصلد.",interpretation:"نمط العتامة الهوائية الموضعية مع Air Bronchograms، في وجود قصة سريرية مناسبة، يتماشى مع التهاب رئوي.",differentialDiagnosis:"تشمل الاحتمالات الأخرى التصلد الرئوي لأسباب مختلفة، أو الانخماص، أو بعض أسباب العتامات القاعدية الأخرى. يجب ربط الصورة بالقصة السريرية.",whatToLookFor:"ابدأ بتقييم جودة الصورة، ثم افحص الرئتين بصورة منهجية، وقارن الجانبين، وحدد موقع العتامة، وابحث عن Air Bronchograms أو علامات فقدان الحجم أو الانصباب الجنبي.",commonMistake:"التركيز على العتامة وحدها دون تقييم حجم الرئة، الزوايا الضلعية الحجابية، والبحث عن علامات قد تشير إلى الانخماص أو الانصباب.",safetyQualityNote:"عند إمكانية ذلك، تُفضّل وضعية PA للمريض القادر على الوقوف بدل AP، مع التأكد من التمركز والاستنشاق والتعرض المناسبين.",finalImpression:"عتامة هوائية موضعية في الرئة اليمنى السفلية مع Air Bronchograms، متوافقة مع الالتهاب الرئوي في السياق السريري المناسب.",takeaway:"اقرأ صورة الصدر بطريقة منهجية: الجودة أولًا، ثم الموقع، ثم نمط العتامة، ثم العلامات المصاحبة، وأخيرًا اربط النتيجة بالقصة السريرية.",status:"PUBLISHED",seo:{title:"حالة سريرية: ذات الرئة | Hidden Radiology",description:"حالة تعليمية متكاملة في أشعة الصدر عن الالتهاب الرئوي.",canonical:"/ar/cases/chest-pneumonia"}},{id:"hr-case-ar-002",language:"ar",slug:"ct-brain-stroke",title:"السكتة الدماغية الحادة — حالة CT",modality:"CT",region:"الدماغ",clinicalContext:"مريض يبلغ من العمر 68 عامًا يعاني من بداية مفاجئة لاضطراب الوعي وضعف في الجانب الأيسر.",indication:"تقييم عاجل لأعراض عصبية مفاجئة مع الاشتباه في سكتة دماغية حادة.",technique:"CT للدماغ بدون تباين وريدي كجزء من التقييم الأولي للسكتة الدماغية الحادة.",image:"/assets/images/ar/cases/ct/brain-hemorrhage_1_1.jpg",imageDescription:"صورة CT للدماغ ضمن تقييم حالة عصبية حادة.",keyFindings:"يجب البحث بصورة منهجية عن النزف داخل القحف، وفقدان التمييز بين المادة الرمادية والبيضاء، والعلامات المبكرة لانسداد شرياني.",interpretation:"في السكتة الإقفارية الحادة قد تكون العلامات المبكرة دقيقة، ولذلك يجب عدم اعتبار غياب النزف علامة على أن الفحص طبيعي.",differentialDiagnosis:"يشمل التشخيص التفريقي النزف داخل القحف، السكتة الإقفارية، وبعض المقلدات السريرية للسكتة. يعتمد التمييز النهائي على الصورة الكاملة والسياق السريري.",whatToLookFor:"افحص أولًا وجود النزف، ثم التمييز بين المادة الرمادية والبيضاء، العقد القاعدية، الشريط الجزيري، الشرايين الدماغية، ووجود وذمة أو تأثير كتلي.",commonMistake:"اعتبار CT طبيعيًا إذا لم يوجد نزف واضح، مع إغفال العلامات الإقفارية المبكرة الدقيقة.",safetyQualityNote:"يُعد CT الدماغ بدون تباين فحصًا أوليًا مهمًا في تقييم السكتة الحادة، مع ضرورة اتباع بروتوكول السكتة المعتمد في المنشأة.",finalImpression:"حالة تعليمية للسكتة الدماغية الحادة تتطلب تقييمًا منهجيًا سريعًا لوجود النزف والعلامات الإقفارية المبكرة.",takeaway:"في CT الدماغ الحاد، غياب النزف لا يعني أن الفحص طبيعي؛ ابحث دائمًا عن العلامات الإقفارية المبكرة الدقيقة.",status:"PUBLISHED",seo:{title:"حالة سريرية: السكتة الدماغية الحادة | Hidden Radiology",description:"حالة تعليمية متكاملة في CT الدماغ لتقييم السكتة الدماغية الحادة.",canonical:"/ar/cases/ct-brain-stroke"}},{id:"brainstem-pontine-lesion-t2",language:"ar",slug:"brainstem-pontine-lesion-t2",title:"آفة جذع الدماغ الخفية - البؤرة الجسرية على T2",modality:"MRI",region:"الدماغ",clinicalContext:"مريضة 34 سنة مع دوخة وتنميل متقطع، MRI للدماغ لاستبعاد آفة مزيلة للميالين. هذه حالة تعليمية لآفة دقيقة في جذع الدماغ.",indication:"تقييم آفة جذع دماغ مشتبه بها.",technique:"MRI Brain T2 Axial.",image:"/assets/images/ar/cases/mri/mri-brain-t2-axial.jpg",imageDescription:"بؤرة صغيرة في pons.",keyFindings:"بؤرة صغيرة عالية الإشارة في المنطقة الظهرية للـ pons (الجسر) على T2، محددة بالسهم في الصور المكبرة. لا يوجد تأثير كتلي كبير أو وذمة محيطة واضحة. موقعها في جذع الدماغ يجعلها سهلة الإغفال بدون تكبير ومراجعة منهجية.",interpretation:"مواصفات متوافقة مع آفة داخل محورية صغيرة في جذع الدماغ. في السياق التعليمي ترجح بؤرة التهابية صغيرة / مزيلة للميالين، مع ضرورة الربط بالسياق السريري والمتابعة.",differentialDiagnosis:"بؤرة مزيلة للميالين (MS)، التهاب جذع دماغي، إقفار صغير، ورم دبقي منخفض الدرجة - يعتمد التمييز على المتابعة والسياق.",whatToLookFor:"راجع جذع الدماغ بشكل منهجي على T2 و FLAIR مع تكبير، ابحث عن بؤر صغيرة غير متناظرة، قارن مع الجانب المقابل، وتأكد من عدم وجود آفات أخرى فوق الخيمة.",commonMistake:"إغفال آفات جذع الدماغ الصغيرة بسبب صغر حجمها وقربها من artifacts النبض، والاكتفاء بمراجعة نصف الكرة المخية فقط.",safetyQualityNote:"تعليمية.",finalImpression:"بؤرة جسرية صغيرة على T2 - درس في أهمية المراجعة المنهجية لجذع الدماغ مع التكبير.",takeaway:"دائماً كبر وراجع جذع الدماغ - الآفات الصغيرة هناك سهلة الإغفال لكنها سريرياً مهمة.",status:"PUBLISHED",seo:{title:"آفة جذع الدماغ",description:"حالة MRI",canonical:"/ar/cases/brainstem-pontine-lesion-t2"}},{id:"cervicothoracic-cord-lesion-enhancement",language:"ar",slug:"cervicothoracic-cord-lesion-enhancement",title:"آفة الحبل الرقبي الصدري - التباين يكشف الخفي",modality:"MRI",region:"العمود الفقري",clinicalContext:"مريض 28 سنة مع ضعف تدريجي في الأطراف السفلية، MRI للعمود الفقري الرقبي الصدري. حالة تعليمية لأهمية الصبغة.",indication:"تقييم آفة حبل.",technique:"MRI T2 & T1 Post-Contrast.",image:"/assets/images/ar/cases/mri/mri-cervicothoracic.png",imageDescription:"بؤرة حبل مع تعزيز.",keyFindings:"على T2: بؤرة عالية الإشارة داخل الحبل الشوكي في المنطقة الرقبية الصدرية. على T1 بعد الصبغة: تعزيز بؤري خفيف في نفس الموقع. وجود التعزيز يغير التفريق بين التهاب وورم.",interpretation:"آفة داخل الحبل الشوكي مع تعزيز بؤري - في السياق التعليمي ترجح التهاب نخاع (myelitis) أو آفة مزيلة للميالين، مع ضرورة المتابعة وربطها بالتحاليل.",differentialDiagnosis:"التهاب نخاع مستعرض، تصلب متعدد، ورم حبلي (ependymoma)، احتشاء حبلي.",whatToLookFor:"قارن T2 مع T1 بعد الصبغة دائماً في آفات الحبل، حدد هل التعزيز بؤري أم حلقي، ابحث عن آفات دماغية مصاحبة.",commonMistake:"الاكتفاء بـ T2 بدون مراجعة التعزيز، مما يؤدي لتشخيص خاطئ بين التهاب وورم.",safetyQualityNote:"تعليمية.",finalImpression:"آفة حبلية مع تعزيز خفيف - أهمية الصبغة في تشخيص آفات الحبل الشوكي.",takeaway:"التعزيز بعد الصبغة يغير التشخيص التفريقي تماماً - لا تهمل مقارنة T1 post-contrast.",status:"PUBLISHED",seo:{title:"آفة الحبل",description:"حالة MRI",canonical:"/ar/cases/cervicothoracic-cord-lesion-enhancement"}},{id:"thoracic-intradural-extramedullary-mass",language:"ar",slug:"thoracic-intradural-extramedullary-mass",title:"كتلة خارج الحبل داخل الأم الجافية - ضغط الحبل الصدري",modality:"MRI",region:"العمود الفقري",clinicalContext:"سيدة 45 سنة مع ألم ظهري مزمن وضعف تدريجي في الأطراف السفلية، MRI للعمود الصدري يظهر كتلة تضغط الحبل الشوكي. حالة تعليمية كلاسيكية للتمييز بين داخل وخارج الحبل.",indication:"تقييم كتلة في القناة الشوكية الصدرية مع أعراض ضغط حبل شوكي.",technique:"MRI Thoracic Spine T1, T2, و T1 بعد الصبغة مع قياس حجم الكتلة ودرجة ضغط الحبل.",image:"/assets/images/ar/cases/mri/mri-ct-thoracic-spine.jpg",imageDescription:"كتلة مستديرة محددة خلف الحبل الشوكي الصدري تدفع الحبل للأمام وتضغطه بشكل واضح. وجود فاصل من السائل النخاعي (CSF cleft) حول الكتلة يؤكد أنها خارج الحبل لكن داخل الأم الجافية.",keyFindings:"كتلة مستديرة محددة الحواف تقع خلف الحبل الشوكي الصدري في الحيز داخل الأم الجافية خارج الحبل (intradural extramedullary). تدفع الحبل الشوكي للأمام وتضغطه بشكل واضح. وجود فاصل من السائل النخاعي CSF cleft حول الكتلة يؤكد موقعها خارج الحبل. لا يوجد وذمة واسعة داخل الحبل لكن يوجد علامات ضغط مزمن.",interpretation:"كتلة intradural extramedullary ضاغطة على الحبل - في السياق التعليمي متوافقة مع meningioma صدري، وهو من أشيع أورام هذه المنطقة عند السيدات في منتصف العمر، خاصة مع قاعدة عريضة على الأم الجافية.",differentialDiagnosis:"Meningioma (الأرجح - خاصة عند سيدة في منتصف العمر مع كتلة خلفية)، schwannoma (يميل للجانب مع توسيع foramen)، neurofibroma.",whatToLookFor:"حدد هل الكتلة داخل الحبل أم خارجه - ابحث عن فاصل CSF، اتجاه دفع الحبل، شكل الكتلة وقاعدتها على الأم الجافية، وهل هناك توسيع للـ foramen العصبي.",commonMistake:"الخلط بين داخل الحبل (intramedullary) وخارجه (extramedullary)، مما يغير الجراحة والتشخيص تماماً. أيضاً إغفال علامة CSF cleft.",safetyQualityNote:"حالة تعليمية فقط - تقييم كتل القناة الشوكية يتطلب مراجعة جراحة أعصاب بشكل عاجل عند وجود ضغط حبل.",finalImpression:"كتلة خارج الحبل داخل الأم الجافية ضاغطة على الحبل الصدري - مثال كلاسيكي لـ meningioma صدري مع علامة CSF cleft المميزة.",takeaway:"فاصل CSF هو المفتاح للتمييز بين داخل وخارج الحبل - ابحث عنه دائماً، وحدد علاقة الكتلة بالأم الجافية والـ foramen.",status:"PUBLISHED",seo:{title:"كتلة خارج الحبل داخل الأم الجافية - ضغط الحبل الصدري",description:"حالة MRI تعليمية لكتلة intradural extramedullary ضاغطة على الحبل الصدري مع علامة CSF cleft",canonical:"/ar/cases/thoracic-intradural-extramedullary-mass"}}]},871:(e,a,i)=>{i.d(a,{J:()=>n});let n=[{id:"hr-case-en-001",language:"en",slug:"chest-pneumonia",title:"Pneumonia — Clinical Case",modality:"Chest X-Ray",region:"Chest",clinicalContext:"A 45-year-old patient presents with cough and fever for 5 days.",indication:"Evaluation of a lower respiratory tract infection with clinical suspicion of pneumonia.",technique:"Chest radiography with assessment of positioning, inspiration, exposure, lung fields, and pleural spaces.",image:"/assets/images/en/cases/xray/Lobaerpneumonie.jpg",imageDescription:"Chest radiograph demonstrating a focal pulmonary air-space opacity.",keyFindings:"There is a focal right lower-lung air-space opacity with air bronchograms within the area of consolidation.",interpretation:"A focal air-space opacity with air bronchograms, in the appropriate clinical setting, is compatible with pneumonia.",differentialDiagnosis:"Other possibilities include consolidation from alternative causes, atelectasis, and other basal pulmonary opacities. Correlation with the clinical presentation is essential.",whatToLookFor:"Start with image quality, then assess both lungs systematically. Localize the opacity, compare both sides, and look for air bronchograms, volume loss, or pleural effusion.",commonMistake:"Focusing only on the opacity without assessing lung volume, costophrenic angles, and associated findings that may suggest atelectasis or pleural disease.",safetyQualityNote:"When appropriate, a PA projection is preferred to AP in an ambulatory patient, with careful attention to positioning, inspiration, and exposure.",finalImpression:"Focal right lower-lung air-space opacity with air bronchograms, compatible with pneumonia in the appropriate clinical context.",takeaway:"Read chest radiographs systematically: assess quality first, then location, pattern, associated signs, and finally correlate with the clinical context.",status:"PUBLISHED",seo:{title:"Clinical Case: Pneumonia | Hidden Radiology",description:"A complete educational chest X-ray case focused on pneumonia.",canonical:"/en/cases/chest-pneumonia"}},{id:"hr-case-en-002",language:"en",slug:"ct-brain-stroke",title:"Acute Stroke — CT Case",modality:"CT",region:"Brain",clinicalContext:"A 68-year-old patient presents with sudden altered consciousness and left-sided weakness.",indication:"Urgent evaluation of sudden neurological symptoms with clinical suspicion of acute stroke.",technique:"Non-contrast head CT as part of the initial assessment of acute stroke.",image:"/assets/images/en/cases/ct/brain-hemorrhage_1_1.jpg",imageDescription:"Brain CT image obtained during evaluation of an acute neurological presentation.",keyFindings:"Systematically assess for intracranial hemorrhage, loss of gray-white matter differentiation, and early arterial hyperdensity.",interpretation:"Early ischemic stroke findings may be subtle; therefore, the absence of hemorrhage does not mean that the CT examination is normal.",differentialDiagnosis:"The differential includes intracranial hemorrhage, acute ischemic stroke, and clinical stroke mimics. Final interpretation requires the complete clinical and imaging context.",whatToLookFor:"First assess for hemorrhage, then evaluate gray-white differentiation, basal ganglia, insular cortex, intracranial arteries, edema, and mass effect.",commonMistake:"Calling the CT normal simply because there is no obvious hemorrhage, while overlooking subtle early ischemic changes.",safetyQualityNote:"Non-contrast head CT is an important first-line examination in acute stroke assessment. Follow the stroke imaging protocol used by the institution.",finalImpression:"Educational acute-stroke case emphasizing rapid systematic assessment for hemorrhage and early ischemic changes.",takeaway:"On acute brain CT, the absence of hemorrhage does not mean a normal study; actively search for subtle early ischemic signs.",status:"PUBLISHED",seo:{title:"Clinical Case: Acute Stroke | Hidden Radiology",description:"A complete educational brain CT case focused on acute stroke assessment.",canonical:"/en/cases/ct-brain-stroke"}},{id:"brainstem-pontine-lesion-t2",language:"en",slug:"brainstem-pontine-lesion-t2",title:"Hidden Brainstem Lesion - Pontine Focus on T2",modality:"MRI",region:"Brain",clinicalContext:"34-year-old female with dizziness and intermittent numbness. MRI brain to exclude demyelination. Educational case of subtle brainstem lesion.",indication:"Evaluation of suspected brainstem lesion.",technique:"MRI Brain T2 Axial with magnification.",image:"/assets/images/ar/cases/mri/mri-brain-t2-axial.jpg",imageDescription:"Small hyperintense focus in dorsal pons.",keyFindings:"Small hyperintense focus in dorsal pons on T2, highlighted by arrow on magnified views. No significant mass effect or surrounding edema. Location in brainstem makes it easy to miss without magnification and systematic review.",interpretation:"Small intra-axial lesion in brainstem. In educational context, favors small inflammatory / demyelinating focus, correlation with clinical context needed.",differentialDiagnosis:"Demyelination (MS), brainstem encephalitis, small infarct, low-grade glioma.",whatToLookFor:"Systematically review brainstem on T2 and FLAIR with magnification, look for small asymmetric foci.",commonMistake:"Missing small brainstem lesions due to small size and pulsation artifacts.",safetyQualityNote:"Educational case only.",finalImpression:"Small pontine focus on T2 - lesson in systematic brainstem review.",takeaway:"Always magnify and review brainstem - small lesions there are easily missed but clinically important.",status:"PUBLISHED",seo:{title:"Hidden Brainstem Lesion",description:"MRI teaching case",canonical:"/en/cases/brainstem-pontine-lesion-t2"}},{id:"cervicothoracic-cord-lesion-enhancement",language:"en",slug:"cervicothoracic-cord-lesion-enhancement",title:"Cervicothoracic Cord Lesion - Enhancement Reveals the Hidden",modality:"MRI",region:"Spine",clinicalContext:"28-year-old male with progressive lower limb weakness, cervicothoracic spine MRI. Educational case on importance of contrast.",indication:"Evaluation of suspected cord lesion.",technique:"MRI Cervicothoracic Spine T2 & T1 Post-Contrast.",image:"/assets/images/ar/cases/mri/mri-cervicothoracic.png",imageDescription:"Intramedullary focus with enhancement.",keyFindings:"T2: hyperintense intramedullary focus in cervicothoracic cord. T1 post-contrast: faint focal enhancement at same site. Enhancement changes differential.",interpretation:"Enhancing intramedullary cord lesion - favors myelitis or demyelination, needs follow-up.",differentialDiagnosis:"Transverse myelitis, MS, ependymoma, cord infarct.",whatToLookFor:"Always compare T2 with post-contrast T1 in cord lesions.",commonMistake:"T2 only without checking enhancement.",safetyQualityNote:"Educational.",finalImpression:"Cord lesion with faint enhancement - importance of contrast in cord lesions.",takeaway:"Enhancement changes differential completely.",status:"PUBLISHED",seo:{title:"Cord Lesion",description:"MRI case",canonical:"/en/cases/cervicothoracic-cord-lesion-enhancement"}},{id:"thoracic-intradural-extramedullary-mass",language:"en",slug:"thoracic-intradural-extramedullary-mass",title:"Intradural Extramedullary Mass",modality:"MRI",region:"Spine",clinicalContext:"Spinal mass compressing cord.",indication:"Evaluation of spinal canal mass.",technique:"MRI Thoracic Spine.",image:"/assets/images/ar/cases/mri/mri-ct-thoracic-spine.jpg",imageDescription:"Rounded mass posterior to thoracic cord.",keyFindings:"Rounded mass posterior to cord pushing cord anteriorly. CSF cleft around mass.",interpretation:"Intradural extramedullary mass - compatible with meningioma.",differentialDiagnosis:"Meningioma, schwannoma.",whatToLookFor:"CSF cleft to differentiate intra vs extramedullary.",commonMistake:"Confusing intra vs extramedullary.",safetyQualityNote:"Educational.",finalImpression:"Compressive extramedullary mass - classic meningioma.",takeaway:"CSF cleft is key.",status:"PUBLISHED",seo:{title:"Extramedullary Mass",description:"MRI case",canonical:"/en/cases/thoracic-intradural-extramedullary-mass"}}]}};